proposedVerificationEnvelope.typescript:
interface RuntimeVerificationEnvelope { envelopeVersion: string; companyId: string; instrumentKey: string; units: VerificationUnitRecord[] }
interface VerificationUnitRecord { ruleOrDefinitionId: string; identity: { irSchemaVersion: string; compilerVersion: string | null; sourceContentVersion: string | null }; verificationStatus: SemanticVerificationStatus; verifierAlgorithmVersion: string; evidenceSetHash: string | null; blocks: VerificationBlock[] }
interface VerificationBlock { findingId: string; findingType: SemanticVerificationFindingType; scope: 'NODE' | 'UNIT'; exprIds: string[]; irPathAsGiven: string | null; reason: string }
